import "net/http"

const panelDocument = `<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light dark"><title>用量看板</title>
<style>:root{--dash-bg:var(--bg-secondary,#f5f7fa);--dash-surface:var(--bg-primary,#fff);--dash-muted:var(--text-secondary,#606266);--dash-text:var(--text-primary,#303133);--dash-border:var(--border-color,#dcdfe6);--dash-primary:var(--primary-color,#409eff);--dash-primary-hover:var(--primary-hover,#79bbff);--dash-danger:var(--danger-color,#f56c6c);--dash-warning:var(--warning-color,#e6a23c);--dash-success:var(--success-color,#67c23a);--dash-radius:var(--app-radius-md,14px);font-family:var(--cpamp-plugin-font-family,Inter,-apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC","Microsoft YaHei",sans-serif)}*{box-sizing:border-box}body{margin:0;min-height:100vh;background:var(--dash-bg);color:var(--dash-text);font-family:inherit;font-size:15px;line-height:1.6}.shell{width:100%;max-width:1440px;margin:0 auto;padding:28px 32px 44px}.head{display:flex;align-items:flex-end;justify-content:space-between;gap:20px;flex-wrap:wrap;margin-bottom:24px}.head-left{min-width:320px}.head h1{margin:5px 0 4px;font-size:28px;line-height:1.25;font-weight:750;letter-spacing:-.015em}.muted,.hint{color:var(--dash-muted)}.hint{font-size:13px}.tabs{display:flex;gap:8px;margin:0 0 22px;padding:5px;width:max-content;max-width:100%;border:1px solid var(--dash-border);border-radius:12px;background:var(--dash-surface);box-shadow:0 1px 2px rgba(15,23,42,.03)}.tab{min-height:40px;padding:9px 20px;border:0;border-radius:8px;background:transparent;color:var(--dash-muted);font:inherit;font-weight:650;cursor:pointer;transition:.18s}.tab:hover{color:var(--dash-primary);background:color-mix(in srgb,var(--dash-primary) 8%,transparent)}.tab.active{color:#fff;background:var(--dash-primary);box-shadow:0 2px 6px color-mix(in srgb,var(--dash-primary) 28%,transparent)}.panel{display:none}.panel.active{display:block}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(290px,1fr));gap:18px}.card{background:var(--dash-surface);border:1px solid var(--dash-border);border-radius:var(--dash-radius);padding:20px;box-shadow:0 2px 8px rgba(15,23,42,.04)}.item{display:grid;gap:15px}.row,.actions{display:flex;align-items:center;gap:12px}.row{justify-content:space-between}.name{font-weight:750;font-size:18px}.box{background:color-mix(in srgb,var(--dash-bg) 68%,var(--dash-surface));border:1px solid var(--dash-border);border-radius:10px;padding:13px 15px}.box strong{font-size:18px}.box span{display:block;color:var(--dash-muted);font-size:13px;margin-top:3px}.meter{height:9px;background:color-mix(in srgb,var(--dash-border) 65%,transparent);border-radius:999px;overflow:hidden}.fill{height:100%;background:var(--dash-success);border-radius:inherit}.fill.warn{background:var(--dash-warning)}.fill.bad{background:var(--dash-danger)}.button{min-height:40px;padding:9px 18px;border:1px solid var(--dash-border);border-radius:10px;background:var(--dash-surface);color:var(--dash-text);font:inherit;font-weight:650;cursor:pointer;transition:.18s}.button:hover{border-color:color-mix(in srgb,var(--dash-primary) 45%,var(--dash-border));color:var(--dash-primary);background:color-mix(in srgb,var(--dash-primary) 5%,var(--dash-surface))}.button.primary{border-color:var(--dash-primary);background:var(--dash-primary);color:#fff}.button.primary:hover{background:var(--dash-primary-hover);color:#fff}.button.danger{color:var(--dash-danger)}.status{min-height:1.5em;margin-top:14px;color:var(--dash-muted);font-size:14px}.status.error{color:var(--dash-danger)}.manage{display:grid;grid-template-columns:320px minmax(0,1fr);gap:18px}.source-list{display:grid;gap:12px;align-content:start}.source-button{width:100%;text-align:left;border:1px solid var(--dash-border);background:var(--dash-surface);border-radius:10px;padding:12px 14px;cursor:pointer;color:var(--dash-text);font:inherit}.source-button:hover{border-color:color-mix(in srgb,var(--dash-primary) 45%,var(--dash-border))}.source-button.active{border-color:var(--dash-primary);background:color-mix(in srgb,var(--dash-primary) 7%,var(--dash-surface));color:var(--dash-primary)}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.field{display:grid;gap:7px}.field.wide{grid-column:1/-1}.field label{font-weight:650;font-size:14px}.field input,.field select,.field textarea{width:100%;min-height:42px;border:1px solid var(--dash-border);border-radius:10px;background:var(--dash-surface);color:var(--dash-text);padding:10px 13px;font:inherit;outline:none}.field textarea{min-height:96px;resize:vertical;font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:14px}.field input:focus,.field select:focus,.field textarea:focus{border-color:var(--dash-primary);box-shadow:0 0 0 3px color-mix(in srgb,var(--dash-primary) 15%,transparent)}.check{display:flex;align-items:center;gap:10px}.check input{width:auto;accent-color:var(--dash-primary)}.auth-fields{display:none}.auth-fields.show{display:grid}.secret-note{border:1px solid color-mix(in srgb,var(--dash-warning) 45%,var(--dash-border));border-left:4px solid var(--dash-warning);border-radius:10px;padding:13px 16px;background:color-mix(in srgb,var(--dash-warning) 7%,var(--dash-surface));font-size:14px}.loading{display:grid;place-items:center;min-height:420px}.spinner{width:36px;height:36px;border:4px solid color-mix(in srgb,var(--dash-primary) 18%,transparent);border-top-color:var(--dash-primary);border-radius:50%;animation:spin .8s linear infinite}.loading-text{margin-top:16px;color:var(--dash-muted);font-weight:600}@keyframes spin{to{transform:rotate(1turn)}}.password-field{display:grid;grid-template-columns:minmax(0,1fr)44px}.password-field button{border-left:0;border-radius:0 10px 10px 0;min-height:42px}.password-field input{border-radius:10px 0 0 10px}@media(max-width:760px){.shell{padding:18px}.head{align-items:start}.manage{grid-template-columns:1fr}.form-grid{grid-template-columns:1fr}.field.wide{grid-column:auto}.tabs{width:100%}.tab{flex:1;justify-content:center}}</style></head>
<body><main class="shell"><header class="head"><div><div class="muted">CLIProxyAPI · 自定义用量源</div><h1>用量看板</h1><div id="summary" class="muted">正在读取…</div></div><button id="refresh" class="button primary">刷新看板</button></header>
<nav class="tabs"><button class="tab active" data-panel="dashboard">看板</button><button class="tab" data-panel="manager">用量源管理</button><button class="tab" data-panel="oauth">OAuth 凭证</button></nav>
<section id="dashboard" class="panel active"><div id="cards" class="grid"></div><div id="dashboard-status" class="status"></div></section>
<template id="loading-template"><div class="loading"><div><div class="spinner"></div><div class="loading-text">正在加载用量数据…</div></div></div></template>
<section id="oauth" class="panel"><div class="manage"><aside class="card source-list"><strong>OAuth 凭证</strong><div class="hint">勾选需要加入看板的 Codex 或 Gemini 凭证。</div><div id="oauth-list"></div></aside><div class="card"><div id="oauth-preview" class="grid"></div><div class="actions"><button id="save-oauth" class="button primary" type="button">保存 OAuth 凭证</button></div><div id="oauth-status" class="status"></div></div></div></section>
<section id="manager" class="panel"><div class="manage"><aside class="card source-list"><div class="row"><strong>用量源</strong><button id="new-source" class="button">新增</button></div><div id="source-list"></div></aside><form id="source-form" class="card"><div class="form-grid">
<div class="field"><label for="source-id">标识</label><input id="source-id" required placeholder="example-service"></div><div class="field"><label for="source-name">名称</label><input id="source-name" required placeholder="Example Service"></div>
<label class="check"><input id="source-enabled" type="checkbox" checked>启用</label><div class="field"><label for="source-method">请求方法</label><select id="source-method"><option>GET</option><option>POST</option></select></div>
<div class="field wide"><label for="source-url">查询地址</label><input id="source-url" type="url" required></div><div class="field"><label for="auth-mode">鉴权来源</label><select id="auth-mode"><option value="custom">自定义查询 Token</option><option value="credential">绑定已有凭证</option><option value="none">不使用 Token</option></select></div>
<div id="custom-auth" class="field auth-fields"><label for="custom-token">查询 Token</label><div class="password-field"><input id="custom-token" type="password" autocomplete="off"><button id="toggle-custom-token" type="button" aria-label="显示或隐藏查询 Token">👁</button></div><div class="hint">用于访问用量查询接口的独立 Token，可能与模型调用 Token 不同。</div></div><div id="credential-auth" class="field auth-fields"><label for="auth-index">已有凭证</label><select id="auth-index"></select><div class="hint">选择 CLIProxyAPI 已保存的 OAuth/API 凭证；Token 不在这里回显，查询时由插件直接读取。</div></div>
<div class="field"><label for="auth-header">Token 请求头</label><input id="auth-header" value="Authorization"></div><div class="field"><label for="auth-prefix">Token 前缀</label><input id="auth-prefix" value="Bearer "></div><div class="field"><label for="auth-field">凭证 Token 字段</label><input id="auth-field" value="access_token"></div>
<div class="field wide"><label for="headers-json">其他请求头 JSON</label><textarea id="headers-json" placeholder='{"Accept":"application/json","X-Tenant-ID":"example"}'></textarea></div><div class="field wide"><label for="request-body">POST 请求体</label><textarea id="request-body"></textarea></div>
<div class="field"><label for="list-path">数据列表路径</label><input id="list-path" placeholder="data.items"></div><div class="field"><label for="field-name">名称字段</label><input id="field-name" placeholder="label"></div>
<div class="field"><label for="field-total">总额度字段</label><input id="field-total" required placeholder="limit"></div><div class="field"><label for="field-used">已用额度字段</label><input id="field-used" required placeholder="consumed"></div>
<div class="field"><label for="field-status">状态字段</label><input id="field-status" placeholder="state"></div><div class="field"><label for="field-reset">重置时间字段</label><input id="field-reset" placeholder="reset_at"></div>
<div class="field"><label for="divisor">除数</label><input id="divisor" type="number" step="any" value="1"></div><div class="field"><label for="multiplier">乘数</label><input id="multiplier" type="number" step="any" value="1"></div><div class="field"><label for="unit">单位</label><input id="unit" placeholder="CNY"></div>
<div class="field wide secret-note"><strong>说明</strong><div class="hint">自定义查询 Token 与模型调用 Token 完全独立，但会保存在 CLIProxyAPI 的 config.yaml 中。绑定凭证模式只读取所选凭证里的指定字段。</div></div>
</div><div class="actions"><button class="button primary" type="submit">保存用量源</button><button id="delete-source" class="button danger" type="button">删除</button></div><div id="manager-status" class="status"></div></form></div></section>
</main><script>(()=>{"use strict";const PLUGIN="` + pluginID + `",AUTH_KEY="cli-proxy-auth",PREFIX="enc::v1::",SALT="cli-proxy-api-webui::secure-storage",OVERVIEW="` + overviewRoute + `",CREDENTIALS="` + credentialsRoute + `";let auth=null,sources=[],credentials=[],oauthSelected=new Set(),editing=-1;
function xor(bytes,key){for(let i=0;i<bytes.length;i++)bytes[i]^=key[i%key.length];return bytes}function decode(raw){if(!raw)return raw;if(raw.startsWith("enc::v2::")){const bytes=Uint8Array.from(atob(raw.slice(9)),c=>c.charCodeAt(0));return new TextDecoder().decode(xor(bytes,new TextEncoder().encode(SALT+"|v2|"+location.host)))}if(raw.startsWith("enc::v1::")){const bytes=Uint8Array.from(atob(raw.slice(9)),c=>c.charCodeAt(0));return new TextDecoder().decode(xor(bytes,new TextEncoder().encode(SALT+"|"+location.host+"|"+navigator.userAgent)))}return raw}function loadAuth(){const raw=localStorage.getItem(AUTH_KEY);if(!raw)throw new Error("请先登录 management.html，并勾选记住管理密钥");const parsed=JSON.parse(decode(raw)),state=parsed.state||parsed,key=state.managementKey;if(!key)throw new Error("管理密钥未保存");return{key,base:new URL("../../../management/",location.href)}}
async function request(path,init){if(!auth)throw new Error("管理会话不可用");init=init||{};const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),60000);try{const response=await fetch(new URL(path.replace(/^\/+/,""),auth.base),{method:init.method||"GET",body:init.body,credentials:"same-origin",cache:"no-store",signal:controller.signal,headers:{Accept:"application/json",...(init.body?{"Content-Type":"application/json"}:{}),Authorization:"Bearer "+auth.key}}),text=await response.text();let data=text;try{data=text?JSON.parse(text):null}catch{}if(!response.ok){const message=data&&data.error?(data.error.message||data.error):text;throw new Error("HTTP "+response.status+(message?" · "+message:""))}return data}finally{clearTimeout(timer)}}
function setStatus(id,message,error){const el=document.getElementById(id);el.textContent=message;el.className="status"+(error?" error":"")}
function setLoading(id){const root=document.getElementById(id);const template=document.getElementById("loading-template");root.textContent="";root.append(template.content.cloneNode(true))}function renderDashboard(data){const root=document.getElementById("cards");root.textContent="";document.getElementById("summary").textContent="共 "+data.summary.total+" 个用量源 · 正常 "+data.summary.ok+" 个 · 异常 "+data.summary.errors+" 个";for(const source of data.sources||[]){if(source.items&&source.items.length){for(const item of source.items){const card=document.createElement("section");card.className="card item";const top=document.createElement("div");top.className="row";const title=document.createElement("div");const name=document.createElement("div");name.className="name";name.textContent=item.name||source.name;const sub=document.createElement("div");sub.className="muted";sub.textContent=source.name+(item.unit?" · "+item.unit:"");title.append(name,sub);const remain=document.createElement("div");remain.className="box";const strong=document.createElement("strong");strong.textContent=Number(item.remaining||0).toFixed(2);const label=document.createElement("span");label.textContent="剩余"+(item.unit||"");remain.append(strong,label);top.append(title,remain);const values=document.createElement("div");values.className="grid";const reset=item.reset_at?new Date(item.reset_at).toLocaleString():"--";for(const pair of [["总额度",Number(item.total||0).toFixed(2)],["已使用",Number(item.used||0).toFixed(2)],["重置时间",reset]]){const box=document.createElement("div");box.className="box";const value=document.createElement("strong");value.textContent=pair[1];const text=document.createElement("span");text.textContent=pair[0];box.append(value,text);values.append(box)}const meter=document.createElement("div");meter.className="meter";const fill=document.createElement("div");const used=Number(item.used_percent||0);fill.className="fill"+(used>=90?" bad":used>=70?" warn":"");fill.style.width=used.toFixed(2)+"%";meter.append(fill);card.append(top,values,meter);root.append(card)}}else{const card=document.createElement("section");card.className="card item";const name=document.createElement("strong");name.textContent=source.name;const error=document.createElement("div");error.className="status error";error.textContent=source.error?source.error.message:"没有数据";card.append(name,error);root.append(card)}}if(!(data.sources||[]).length){const empty=document.createElement("div");empty.className="card";empty.textContent="还没有用量源，请切换到“用量源管理”添加。";root.append(empty)}}
async function loadDashboard(force){setLoading("cards");setStatus("dashboard-status",force?"正在刷新上游数据…":"正在读取…",false);try{const data=await request(OVERVIEW+(force?"?refresh=true":""));renderDashboard(data);setStatus("dashboard-status","更新时间："+new Date(data.generated_at).toLocaleString()+(data.cached?" · 缓存":""),false)}catch(error){setStatus("dashboard-status",error.message,true)}}
function authVisibility(){const mode=document.getElementById("auth-mode").value;document.getElementById("custom-auth").classList.toggle("show",mode==="custom");document.getElementById("credential-auth").classList.toggle("show",mode==="credential")}
function sourceFromForm(){let headers={};const raw=document.getElementById("headers-json").value.trim();if(raw)headers=JSON.parse(raw);return{id:document.getElementById("source-id").value.trim(),name:document.getElementById("source-name").value.trim(),enabled:document.getElementById("source-enabled").checked,method:document.getElementById("source-method").value,url:document.getElementById("source-url").value.trim(),auth_mode:document.getElementById("auth-mode").value,custom_token:document.getElementById("custom-token").value,auth_index:document.getElementById("auth-index").value,auth_field:document.getElementById("auth-field").value.trim(),auth_header:document.getElementById("auth-header").value.trim(),auth_prefix:document.getElementById("auth-prefix").value,headers:headers,body:document.getElementById("request-body").value,list_path:document.getElementById("list-path").value.trim(),field_name:document.getElementById("field-name").value.trim(),field_total:document.getElementById("field-total").value.trim(),field_used:document.getElementById("field-used").value.trim(),field_status:document.getElementById("field-status").value.trim(),field_reset_at:document.getElementById("field-reset").value.trim(),divisor:Number(document.getElementById("divisor").value)||1,multiplier:Number(document.getElementById("multiplier").value)||1,unit:document.getElementById("unit").value.trim()}}
function fillForm(source,index){editing=index;source=source||{enabled:true,method:"GET",auth_mode:"custom",auth_header:"Authorization",auth_prefix:"Bearer ",auth_field:"access_token",headers:{},divisor:1,multiplier:1};for(const pair of [["source-id",source.id],["source-name",source.name],["source-url",source.url],["custom-token",source.custom_token],["auth-field",source.auth_field],["auth-header",source.auth_header],["auth-prefix",source.auth_prefix],["request-body",source.body],["list-path",source.list_path],["field-name",source.field_name],["field-total",source.field_total],["field-used",source.field_used],["field-status",source.field_status],["field-reset",source.field_reset_at],["divisor",source.divisor],["multiplier",source.multiplier],["unit",source.unit]])document.getElementById(pair[0]).value=pair[1]==null?"":pair[1];document.getElementById("source-enabled").checked=source.enabled!==false;document.getElementById("source-method").value=source.method||"GET";document.getElementById("auth-mode").value=source.auth_mode||"custom";document.getElementById("auth-index").value=source.auth_index||"";document.getElementById("headers-json").value=JSON.stringify(source.headers||{},null,2);authVisibility();renderSourceList()}
function renderSourceList(){const root=document.getElementById("source-list");root.textContent="";sources.forEach((source,index)=>{const button=document.createElement("button");button.type="button";button.className="source-button"+(index===editing?" active":"");button.textContent=(source.enabled===false?"[停用] ":"")+(source.name||source.id);button.addEventListener("click",()=>fillForm(source,index));root.append(button)})}
function oauthLabel(item){return (item.label||item.email||item.name)+" · "+(item.provider||item.type||"未知")}
function renderOAuthList(){const root=document.getElementById("oauth-list");root.textContent="";if(!credentials.length){const empty=document.createElement("div");empty.className="hint";empty.textContent="没有可用 OAuth 凭证";root.append(empty);return}for(const item of credentials){if(!["codex","gemini","gemini-cli","antigravity"].includes(String(item.provider||item.type).toLowerCase()))continue;const label=document.createElement("label");label.className="check source-button";const checkbox=document.createElement("input");checkbox.type="checkbox";checkbox.checked=oauthSelected.has(item.auth_index);checkbox.addEventListener("change",()=>{if(checkbox.checked)oauthSelected.add(item.auth_index);else oauthSelected.delete(item.auth_index)});const text=document.createElement("span");text.textContent=oauthLabel(item);label.append(checkbox,text);root.append(label)}}
async function saveOAuth(){try{await request("plugins/"+PLUGIN+"/config",{method:"PATCH",body:JSON.stringify({"oauth-auth-indexes":Array.from(oauthSelected)})});setStatus("oauth-status","已保存并重载插件配置。",false);await loadDashboard(true)}catch(error){setStatus("oauth-status",error.message,true)}}
async function loadConfig(){const data=await request("plugins/"+PLUGIN+"/config");sources=Array.isArray(data.sources)?data.sources:[];oauthSelected=new Set(Array.isArray(data["oauth-auth-indexes"])?data["oauth-auth-indexes"]:[]);renderSourceList();renderOAuthList();if(editing<0)fillForm(null,-1)}
async function saveSources(){await request("plugins/"+PLUGIN+"/config",{method:"PATCH",body:JSON.stringify({sources:sources})});setStatus("manager-status","已保存并重载插件配置。",false);await loadDashboard(true)}
async function loadCredentials(){const data=await request(CREDENTIALS);credentials=data.credentials||[];renderOAuthList();const select=document.getElementById("auth-index");select.textContent="";const empty=document.createElement("option");empty.value="";empty.textContent="请选择凭证";select.append(empty);for(const item of data.credentials||[]){const option=document.createElement("option");option.value=item.auth_index||"";option.textContent=(item.label||item.email||item.name)+" · "+(item.provider||item.type||"未知");select.append(option)}}
document.querySelectorAll(".tab").forEach(button=>button.addEventListener("click",()=>{document.querySelectorAll(".tab").forEach(x=>x.classList.toggle("active",x===button));document.querySelectorAll(".panel").forEach(x=>x.classList.toggle("active",x.id===button.dataset.panel))}));document.getElementById("auth-mode").addEventListener("change",authVisibility);document.getElementById("toggle-custom-token").addEventListener("click",()=>{const input=document.getElementById("custom-token");input.type=input.type==="password"?"text":"password"});document.getElementById("refresh").addEventListener("click",()=>loadDashboard(true));document.getElementById("save-oauth").addEventListener("click",saveOAuth);document.getElementById("new-source").addEventListener("click",()=>fillForm(null,-1));document.getElementById("delete-source").addEventListener("click",async()=>{if(editing<0)return;sources.splice(editing,1);editing=-1;await saveSources();await loadConfig()});document.getElementById("source-form").addEventListener("submit",async event=>{event.preventDefault();try{const source=sourceFromForm();if(!source.id||!source.name||!source.url||!source.field_total||!source.field_used)throw new Error("请填写所有必填项");if(editing>=0)sources[editing]=source;else{if(sources.some(x=>x.id===source.id))throw new Error("标识不能重复");sources.push(source);editing=sources.length-1}await saveSources();await loadConfig()}catch(error){setStatus("manager-status",error.message,true)}});try{auth=loadAuth();Promise.all([loadCredentials(),loadConfig(),loadDashboard(false)]).catch(error=>setStatus("manager-status",error.message,true))}catch(error){setStatus("dashboard-status",error.message,true)}})();</script></body></html>`

func panelResponse() managementResponse {
	return managementResponse{StatusCode: http.StatusOK, Headers: http.Header{
		"Content-Type": {"text/html; charset=utf-8"}, "Cache-Control": {"no-store"}, "X-Content-Type-Options": {"nosniff"}, "Referrer-Policy": {"no-referrer"},
	}, Body: []byte(panelDocument)}
}
